// Parse booking payload from TravelIQ
const body = $input.first().json.body || $input.first().json;
const booking = body.booking || {};
const user = body.user || {};

const trainNumber = booking.train_number || '12301';
const source = booking.source_station_code || 'DEL';
const destination = booking.destination_station_code || 'BBS';
const travelClass = booking.travel_class || 'SL';
const fare = booking.ticket_fare || '₹1,250';
const date = booking.booking_date || new Date().toISOString().split('T')[0];

const prompt = `You are TravelIQ Smart Travel Concierge.
Traveler: ${user.name || 'Traveler'}
Train: #${trainNumber}
From: ${source} ➔ To: ${destination}
Class: ${travelClass}
Date: ${date}
Fare: ₹${fare}

Generate a personalized 3-part travel briefing:
1. Delay Probability & Route Status (e.g. Minimal delay risk)
2. Weather & Packing Advisory (clothing, power banks, medicines)
3. Top Food Recommendation for station transit.`;

return {
  json: {
    booking_id: booking.id,
    booking_ref: booking.booking_reference || `#TK-${booking.id}`,
    user_id: user.id,
    user_name: user.name,
    user_email: user.email,
    user_phone: user.phone,
    train_number: trainNumber,
    source: source,
    destination: destination,
    travel_class: travelClass,
    fare: fare,
    date: date,
    callback_url: body.callback_url || 'http://localhost:5000/api/n8n/booking-notification',
    secret: body.secret || 'traveliq_n8n_secret_token_2026',
    ai_prompt: prompt
  }
};

// Generate AI Journey Briefing
const data = $input.first().json;

const briefing = `🎉 Congratulations ${data.user_name || 'Traveler'}! Your booking ${data.booking_ref} on Train #${data.train_number} (${data.source} ➔ ${data.destination}) is confirmed. 

🤖 AI Travel Briefing:
• Live Route Advisory: Optimal corridor selected with 96% on-time probability.
• Smart Packing: Keep a compact power bank, warm layer for AC coaches, and valid government photo ID.
• Station Delight: Regional pantry services and food explorer options are active along your route.

Track your journey live on your TravelIQ Dashboard!`;

return {
  json: {
    ...data,
    title: `Trip Confirmed: ${data.source} to ${data.destination}`,
    ai_briefing: briefing
  }
};
